-- Fix : le composant trombinoscope cherche 'soprane' (terme français) dans le nom du pupitre
-- pour appliquer la couleur, pas 'soprano' — d'où l'absence de couleur sur ce pupitre.
update voice_parts set name = 'Soprane' where name = 'Soprano';

-- Choristes régénérés : noms plus variés (max 2 répétitions de nom de famille sur 70),
-- adresses réelles à Angers + communes alentour (Trélazé, Avrillé, Bouchemaine,
-- Saint-Barthélemy-d'Anjou, Les Ponts-de-Cé, Beaucouzé) avec lat/lng pour la carte,
-- photos (randomuser.me, portraits libres d'usage pour ce type de démo),
-- et 5 choristes qui masquent volontairement un ou plusieurs champs :
--   Fabien Nicolas: masque address, email
--   Damien Regnier: masque address, email, phone
--   Julie Girard: masque address, email, phone
--   Julien Arnaud: masque email
--   Gabriel Francois: masque email, phone

delete from members where email like '%@example.fr' and email not in ('camille.vidal@example.fr', 'julien.leroux@example.fr');

on conflict (email) do nothing;

select m.id, (select id from seasons where active = true)
from members m
where m.email like '%@example.fr'
on conflict do nothing;

-- Julien (pianiste) : adresse + photo. Camille garde sa photo existante (stock) mais reçoit une adresse.
update members set
  address = '33 rue des Écoles',
  zip_code = '49000', city = 'Angers', lat = 47.468970, lng = -0.567966,
  photo_url = 'https://randomuser.me/api/portraits/men/48.jpg'
where email = 'julien.leroux@example.fr';

update members set
  address = 'rue Plantagenêt', zip_code = '49000', city = 'Angers',
  lat = 47.476517, lng = -0.553518
where email = 'camille.vidal@example.fr';
